// @generated by:gauntlet run:alloo-production
import { expect, it } from "vitest";
import {
  backendReleaseIssues,
  frontendReleaseIssues,
  httpsOrigin,
  releaseTargetIssues,
} from "./release";

it("T-PROD-RELEASE rejects local and path-bearing release origins", () => {
  for (const value of [
    undefined,
    "http://localhost:3000",
    "https://localhost",
    "https://alloo.test",
    "https://alloo.workers.dev/path",
    "https://user:pass@alloo.workers.dev",
  ])
    expect(httpsOrigin(value)).toBe(false);
  expect(httpsOrigin("https://alloo.workers.dev")).toBe(true);
});
it("T-PROD-RELEASE refuses missing frontend configuration", () => {
  expect(frontendReleaseIssues({})).toEqual([
    "ALLOO_PUBLIC_ORIGIN",
    "VITE_CONVEX_URL",
    "VITE_SUPPORT_EMAIL",
  ]);
  expect(
    frontendReleaseIssues({
      ALLOO_PUBLIC_ORIGIN: "https://alloo.workers.dev",
      VITE_CONVEX_URL: "https://example.convex.cloud",
      VITE_SUPPORT_EMAIL: "support@example.com",
    }),
  ).toEqual([]);
});
it("T-PROD-RELEASE requires real backend providers and disabled development bypasses", () => {
  const issues = backendReleaseIssues({
    SITE_URL: "https://alloo.workers.dev",
    ALLOO_DEV_AUTH: "true",
    TURN_URLS: "https://relay.example.com",
  });
  expect(issues).toEqual(
    expect.arrayContaining([
      "ALLOO_DEV_AUTH",
      "TURN_URLS",
      "AUTH_RESEND_KEY",
      "ALLOO_OPERATOR_IDS",
    ]),
  );
});
it("T-PROD-RELEASE binds the compiled frontend to the exact verified backend", () => {
  const env = {
    ALLOO_PUBLIC_ORIGIN: "https://alloo.workers.dev",
    VITE_CONVEX_URL: "https://a.convex.cloud",
  };
  expect(
    releaseTargetIssues(env, {
      siteUrl: env.ALLOO_PUBLIC_ORIGIN,
      backendUrl: "https://b.convex.cloud",
    }),
  ).toEqual(["BACKEND_URL_MISMATCH"]);
  expect(
    releaseTargetIssues(env, { siteUrl: env.ALLOO_PUBLIC_ORIGIN, backendUrl: env.VITE_CONVEX_URL }),
  ).toEqual([]);
});
